-- READ-ONLY PREFLIGHT for Plan B (a person runs it against the target database; it changes NOTHING). 10 Nov 2026.
-- Answers three questions before any Plan B migration is applied: (1) is everything the proposals depend on there? (2) is any Plan B object already there (a half-applied or earlier attempt)? (3) is the data in the shape the proposals assume?
-- Read the "status" column: every row should say OK. "MISSING" under a dependency, or "ALREADY PRESENT" under Plan B objects, means STOP and ask. Prints no client data.
with need_tables(t) as (values ('activity_log'),('agreements'),('businesses'),('client_quotations'),('crew_support_requests'),('crew_support_slots'),('employing_entities'),('enquiries'),('entity_registrations'),('entity_signatories'),('leave_requests'),('profiles'),('roles'),('user_roles'),('payments'),('payment_receipt_jobs'),('notification_preferences'),('contacts')),
need_cols(t, c) as (values ('enquiries','crm_stage'),('enquiries','amount_due'),('enquiries','amount_paid'),('enquiries','payment_status'),('enquiries','commercial_intent'),('enquiries','created_by'),('enquiries','user_id'),('enquiries','email'),('enquiries','reference_number'),('enquiries','full_name'),('enquiries','service'),
  ('client_quotations','payment_condition'),('client_quotations','deposit_percent'),('client_quotations','payment_booking_terms'),('client_quotations','accepted_at'),('client_quotations','issued_at'),('client_quotations','enquiry_id'),('client_quotations','crew_support_request_id'),('client_quotations','status'),
  ('profiles','member_number'),('profiles','access_status'),('crew_support_requests','call_time'),('crew_support_requests','finish_time'),('crew_support_requests','event_timezone'),('payments','reference_amount_usd'),('payments','status')),
need_funcs(f) as (values ('private.entity_issue_standing'),('private.is_super_admin'),('public.ordift_studios_business_id')),
plan_b_tables(t) as (values ('booking_rule_settings'),('enquiry_booking_confirmations'),('enquiry_booking_segments'),('booking_notification_jobs'),('cancellation_financial_decisions')),
plan_b_funcs(f) as (values ('public.confirm_ordinary_booking'),('public.cancel_ordinary_booking'),('public.preview_booking_conflicts'),('public.claim_booking_notification_job'),('public.finish_booking_notification_job'),('public.defer_booking_client_notice'),('public.request_cancellation_financial_action'),('public.decide_cancellation_financial_action'),('public.record_cancellation_financial_execution'),('private.booking_conflicts'),('private.booking_actor_is_super_admin'),('private.booking_actor_level'))
select 'dependency table' as kind, t as item, case when to_regclass('public.' || t) is not null then 'OK' else 'MISSING' end as status, '' as detail from need_tables
union all select 'dependency column', t || '.' || c, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = t and column_name = c) then 'OK' else 'MISSING' end, '' from need_cols
union all select 'dependency function', f, case when exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname || '.' || p.proname = f) then 'OK' else 'MISSING' end, '' from need_funcs
union all select 'dependency enum value', 'crm_stage = ' || v, case when exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid where t.typname = 'crm_stage' and e.enumlabel = v) then 'OK' else 'MISSING' end, '' from (values ('quotation_sent'),('booked')) x(v)
union all select 'plan B object absent', 'table ' || t, case when to_regclass('public.' || t) is null then 'OK' else 'ALREADY PRESENT' end, '' from plan_b_tables
union all select 'plan B object absent', 'function ' || f, case when exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname || '.' || p.proname = f) then 'ALREADY PRESENT' else 'OK' end, '' from plan_b_funcs
union all select 'plan B object absent', 'column enquiry_booking_confirmations.cancellation_outcome', case when exists (select 1 from information_schema.columns where table_name = 'enquiry_booking_confirmations' and column_name = 'cancellation_outcome') then 'ALREADY PRESENT' else 'OK' end, ''
union all select 'plan B object absent', 'trigger crew_requests_booking_overlap_guard', case when exists (select 1 from pg_trigger where tgname in ('crew_requests_booking_overlap_guard', 'crew_slots_booking_overlap_guard')) then 'ALREADY PRESENT' else 'OK' end, ''
union all select 'data', 'an active Super Admin exists (the first rules version is seeded from one)', case when exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id join public.profiles p on p.id = ur.user_id where r.slug = 'super_admin' and p.access_status = 'active') then 'OK' else 'MISSING' end, ''
union all select 'data', 'legacy projects already at "booked" by a payment (they will read "Booked (no booking record)")', 'INFO', (select count(*)::text from public.enquiries e where e.crm_stage::text = 'booked' and coalesce(e.commercial_intent, '') <> 'creative_crew_support' and exists (select 1 from public.activity_log a where a.entity_id = e.id::text and a.action = 'enquiry.stage_change' and a.metadata ->> 'reason' = 'full_payment'))
union all select 'data', 'payments awaiting verification right now (do not flip the switch while a person is about to approve one)', 'INFO', (select count(*)::text from public.payments where status in ('awaiting_verification', 'additional_info_required'))
union all select 'data', 'enquiries total / staff-recorded (never auto-mailed) / with a portal owner (verified route)', 'INFO', (select count(*) || ' / ' || count(*) filter (where created_by is not null) || ' / ' || count(*) filter (where user_id is not null) from public.enquiries)
union all select 'ledger', 'latest applied migration version', 'INFO', case when to_regclass('supabase_migrations.schema_migrations') is null then 'ledger table not present in this database' else (xpath('/row/v/text()', query_to_xml('select max(version) as v from supabase_migrations.schema_migrations', false, true, '')))[1]::text end
order by 1, 2;
